// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the value to set and the caller address (actor). The property:
    // On the reference, calling SetMinSum as a non-initialized contract should succeed and update MinSum.
    // The mutant that inverts the initialization guard will revert instead for those inputs.
    function testFuzz_property(uint256 val, address actor) public {
        // Keep actor as a regular addressable actor
        vm.assume(actor != address(0));

        // ensure actor has some ETH so it can call if needed (not strictly required here)
        vm.deal(actor, 1 ether);

        // Act: call SetMinSum as actor and record whether call succeeded and the resulting MinSum
        bool ok;
        uint before = c.MinSum();

        vm.prank(actor);
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        uint after = c.MinSum();

        // The universal property we assert: on the correct contract (reference) SetMinSum should succeed
        // from an uninitialized state and set MinSum to the provided value. The test observes c via its
        // public getter MinSum(). This will fail on the mutant for inputs where the mutant reverts
        // (ok == false) or does not update MinSum (after != val).
        assertTrue(ok && after == val);
    }
}

