pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the value to set as MinSum and an arbitrary caller address
    function testFuzz_property(uint256 val, address caller) public {
        // keep caller as a nonzero address to be realistic, but otherwise wide
        vm.assume(caller != address(0));

        // ensure caller has some ether so calls that might be payable won't fail due to balance
        vm.deal(caller, 1 ether);

        // act as caller and attempt to set MinSum to val
        bool ok;
        vm.prank(caller);
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract: on a fresh contract (not initialized) SetMinSum should succeed
        // and MinSum should equal the provided val. The mutant will revert here making ok==false
        // (and MinSum unchanged). We assert the property as a single assertTrue reading c's public getter.
        // If SetMinSum reverted, ok will be false and this will fail for some inputs on the mutant.
        assertTrue(ok && c.MinSum() == val);
    }
}

