pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newMin) public {
        // keep newMin wide but bounded to a reasonable uint to avoid overly large numbers
        newMin = bound(newMin, 0, type(uint256).max);

        // 1) Set an initial MinSum before initialization
        c.SetMinSum(1);
        // 2) Initialize the contract
        c.Initialized();

        // 3) Attempt to change MinSum after initialization and observe whether SetMinSum succeeds
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract enforces a guard: after Initialized() SetMinSum must not succeed in changing MinSum.
        // Therefore either the call reverts (ok == false) or, if it did not revert, MinSum must remain the original value (1).
        // The single assertion reads c's public getter to ensure the reference behavior holds for all inputs
        assertTrue( (ok == false) || (c.MinSum() == 1) );
    }
}

