    // (when not yet initialized) and set MinSum to this value; the mutant always reverts.
    function testFuzz_property(uint256 newMin) public {
        // keep wide domain; no need to bound newMin
        // Ensure contract is not initialized so SetMinSum is allowed
        // (reference has a flag 'intitalized' that defaults to false)

        // Call SetMinSum and capture whether it succeeded using try/catch
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always allows SetMinSum (when not initialized) and thus
