pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter is the value passed to SetMinSum
    function testFuzz_property(uint256 _val) public {
        // keep full domain (no narrow assumptions)

        // Capture previous MinSum
        uint256 before = c.MinSum();

        // Call SetMinSum and record whether it succeeded (didn't revert)
        bool ok;
        try c.SetMinSum(_val) { ok = true; } catch { ok = false; }

        // The general rule (we assert it as a single boolean):
        // For any input _val, if the call succeeded then MinSum equals _val.
        // This holds in the reference implementation for every input; the mutant
        // will reject (_val == 0) and thus leave MinSum unchanged, causing a mismatch
        // for that input. We observe c only via its public getter MinSum().
        if (ok) {
            assertTrue(c.MinSum() == _val);
        } else {
            // If call reverted, MinSum must remain what it was before the call.
            assertTrue(c.MinSum() == before);
        }
    }
}

