pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: for any uint256 v, calling SetMinSum(v) should set MinSum to v on the correct contract.
    // The mutant adds `require(_val != 0)` and thus will reject v==0 (leaving MinSum unchanged or reverting).
    function testFuzz_property(uint256 v) public {
        // Keep domain wide: allow any uint256 (including 0) so the fuzzer can find v==0 which distinguishes the mutant
        // call SetMinSum and catch revert to observe if call succeeded
        bool ok;
        try c.SetMinSum(v) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, then MinSum must equal the provided v (this holds for the reference for all v,
        // and the mutant fails to satisfy it for v==0 because it reverts and ok==false)
        if (ok) {
            assertTrue(c.MinSum() == v);
        } else {
            // If call reverted, then we still assert that MinSum is not equal to v to ensure divergence is observable.
            // However, per the requirement of a single assertTrue reading c's public surface, we must assert something
            // that the reference satisfies for all inputs and the mutant breaks for some input. The reference never
            // reverts, so ok==false can only happen on the mutant; to keep a single assertTrue that reads c, we
            // assert that MinSum() != v in this branch — the reference would never enter this branch (ok==false),
            // but the branch's assertTrue still reads c's public getter.
            assertTrue(c.MinSum() != v);
        }
    }
}

