pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 v1) public {
        // keep caller non-zero to be a meaningful EOA (fuzzer may pass zero)
        if (caller == address(0)) caller = address(1);

        // Precondition: ensure contract not initialized yet
        // call Initialized() only if needed — we want to test effect of SetMinSum when not initialized
        // Ensure caller has some ETH in case future tests need it (not required here)
        vm.deal(caller, 1 ether);

        // First call SetMinSum as caller with value v1
        vm.prank(caller);
        bool ok1;
        try c.SetMinSum(v1) { ok1 = true; } catch { ok1 = false; }

        // Immediately attempt to call SetMinSum again with the same caller and same value
        vm.prank(caller);
        bool ok2;
        try c.SetMinSum(v1) { ok2 = true; } catch { ok2 = false; }

        // General rule: In the reference contract, calling SetMinSum does NOT flip `intitalized` to true,
        // so repeated calls (when previously uninitialized) should both succeed (ok1 && ok2 == true).
        // The mutant sets intitalized = true inside SetMinSum, causing the second call to revert (ok2 == false)
        // for some inputs; we assert the universal property the reference satisfies: both calls should succeed.
        assertTrue(ok1 && ok2);
    }
}

