pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed actor address; the property concerns whether SetLogFile can be called successfully
    // before Initialized() is called. We let the fuzzer supply an address to act as the log contract.
    function testFuzz_property(address logAddr) public {
        // Keep address non-zero to be admissible (zero address is still admissible for reference but
        // setting a zero address as a contract address is non-useful; still allow it but avoid spurious constraints).
        // No tight constraints so the fuzzer can find addresses that are contracts in the mutated harness environment.
        // Deploy a simple Log-compatible contract at the provided address if it is an EOA (fuzzer-provided address can't
        // be used to deploy to arbitrarily; instead we deploy our own Log and ignore logAddr content).

        // Deploy a real Log contract to pass its address to SetLogFile. This ensures SetLogFile expects a contract address.
        Log helperLog = new Log();

        // Call SetLogFile BEFORE Initialized(). According to the reference contract, this SHOULD succeed (it allows
        // setting as long as intitalized==false). The mutant inverts the guard and will revert here.
        bool ok;
        try c.SetLogFile(address(helperLog)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: reference contract allows SetLogFile before Initialized(), so for ALL inputs
        // the call should succeed and ok == true. The mutant will make some inputs (any call before Initialized())
        // fail, yielding ok == false. Assert that the call succeeded on the deployed contract c.
        assertTrue(ok);
    }
}

// Minimal Log contract matching the reference's expected interface
contract Log {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

