// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address that will act as the Log contract (we'll deploy a malicious reentrant Log) and an amount
    function testFuzz_property(address attackerAddr, uint256 fund) public {
        // keep fund in a reasonable range so vm.deal works but wide enough
        fund = bound(fund, 0, 1 ether);

        // deploy a malicious Log that when AddMessage is called will try to call back into C.SetLogFile
        ReentrantLogger attacker = new ReentrantLogger(address(c));

        // fund the attacker so it can perform any payable calls if needed
        vm.deal(address(attacker), 1 ether);

        // Now call SetLogFile with the attacker's address as the log contract.
        // We must observe whether the call to SetLogFile returns (ok==true) or reverts (ok==false).
        bool ok;
        try c.SetLogFile(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: In the reference implementation, SetLogFile checks intitalized then assigns LogFile
        // without setting intitalized until Initialized() is called; therefore a malicious Log contract
        // that reenters during SetLogFile cannot observe intitalized==true and cannot change the reentry
        // outcome in the way the mutant does. We assert that SetLogFile did NOT unexpectedly succeed in a way
        // that would only be possible if intitalized had been set to true early — i.e., we assert that either
        // the call succeeded (ok==true) which is the normal allowed path, or if it reverted (ok==false) that
        // is still consistent. For the mutated version, certain reentrant behaviors will produce a different
        // visible ok value; the fuzzer will find such inputs. Here we assert that the call did not both
        // succeed AND cause intitalized to appear true immediately (which would indicate the mutant behavior).
        // We only may observe c via its public getters. intitalized has no getter, but we can detect the effect
        // by trying to call SetLogFile again: in the reference, the second call should still be allowed (since
        // intitalized remains false until Initialized), but in the mutant the second call would revert because
        // intitalized would have been set true earlier. Thus we perform a second attempt and assert on that.

        // Second attempt to observe whether c now blocks SetLogFile (which would indicate mutant behavior)
        bool ok2;
        try c.SetLogFile(address(0x1234)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Single assertion: in the reference contract, after the first SetLogFile call completes, the contract
        // should still allow a subsequent SetLogFile call (ok2 == true) for all inputs; the mutant sets
        // intitalized early causing ok2 == false for some inputs (attacker that reenters). We assert that ok2 is true.
        assertTrue(ok2);
    }
}

// Adversarial helper: when AddMessage is called, reenter C.SetLogFile to attempt to exploit ordering
contract ReentrantLogger {
    address public target;
    constructor(address _t) { target = _t; }

    // signature matches AddMessage(address,uint,string)
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // try to reenter SetLogFile on the target to trigger ordering-sensitive behavior
        // we call with our own address
        // ignore success/failure
        (bool s, ) = target.call(abi.encodeWithSignature("SetLogFile(address)", address(this)));
        s;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: actor address and a lockTime value and an amount to send
    function testFuzz_property(address actor, uint64 lockTime1, uint64 lockTime2, uint128 amount) public {
        // keep wide but sensible bounds so arithmetic and vm.deal make sense
        vm.assume(actor != address(0));
        // bound amounts to avoid overflow in vm.deal and excessive gas cost
        amount = uint128(bound(amount, 0, 1 ether));
        // two lock times are 0..1e9 to keep block.timestamp+lockTime in uint range
        lockTime1 = uint64(bound(lockTime1, 0, 1e9));
        lockTime2 = uint64(bound(lockTime2, 0, 1e9));

        // fund the actor so payable calls succeed
        vm.deal(actor, uint256(amount));

        // first put to establish an initial unlockTime
        vm.prank(actor);
        c.Put{value: uint256(amount)}(uint256(lockTime1));

        // read the stored unlockTime after first Put
        (, bytes memory data1) = address(c).call(abi.encodeWithSignature("Acc(address)", actor));
        // cannot decode the mapping struct via low-level call easily; instead rely on public getter for Acc
        // The autogenerated getter for mapping to struct provides the tuple (unlockTime, balance)
        (uint256 u1, uint256 b1) = c.Acc(actor);

        // second put with potentially different lock time
        vm.prank(actor);
        c.Put{value: 0}(uint256(lockTime2));

        // read the stored unlockTime after second Put
        (uint256 u2, uint256 b2) = c.Acc(actor);

        // General rule: reference contract guarantees unlockTime never decreases after a Put call
        // i.e., u2 >= u1 for all inputs. The mutant that overwrites unlockTime can make u2 < u1.
        assertTrue(u2 >= u1);
    }
}

