// Minimal Log helper matching the original contract's interface, but exposing a HistoryLength getter for the test to read
contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    // convenience getter because solidity doesn't auto-generate a .length getter named HistoryLength
    function HistoryLength() public view returns (uint256) {
        return History.length;
    }
}

