        vm.prank(actor);
        if (putAmt > 0) {
            // call Put directly with value
            c.Put{value: putAmt}(0);
        } else {
            // zero put: still ensure mapping entry exists by sending 0 via Put
            c.Put{value: 0}(0);
        }

        // record balance before Collect (public getter Acc(actor) returns (unlockTime,balance) tuple)
        // Note: the autogenerated getter for Acc returns (uint,uint)
        (uint preUnlock, uint preBal) = c.Acc(actor);

        // ensure MinSum is low so that condition acc.balance>=MinSum doesn't block; MinSum default is 0
        // ensure unlockTime in past so block.timestamp>unlockTime holds: we can warp forward
        if (preUnlock >= block.timestamp) {
            vm.warp(preUnlock + 1);
        }

        // attempt Collect and observe whether it returns or reverts
        bool ok;
        try c.Collect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // one universal assertion: on the correct contract, whenever Collect returns successfully,
        // the stored balance equals prior balance minus collectAmt (no other change). This reads c via public getter.
        if (ok) {
            (, uint postBal) = c.Acc(actor);
            assertTrue(postBal == preBal - collectAmt);
        } else {
            // if call reverted, then we assert that this does not violate the universal property because
            // the property only claims balance decrease on successful return; so we assert true as placeholder
            // but we must use exactly one assertTrue in the function. To satisfy that, when ok==false we assert
            // that ok == false implies the universal property holds vacuously; express as assertTrue(ok || true)
            // however assertTrue must read c. So read c.address balance and assert something trivial about it.
            // Use: when Collect reverted, the contract's ether balance did not increase by collectAmt (i.e., address(c).balance <= address(c).balance + 0)
            // But we must use a single assertTrue overall. To comply, we restructure: always make a single assertTrue below.
        }

        // Single assertTrue reading c: If ok then postBal == preBal - collectAmt, else ok==false (a reachable observable)
        // We materialize this by reading Acc(actor) and forming the condition.
        (, uint finalBal) = c.Acc(actor);
        bool prop = true;
        if (ok) {
            prop = (finalBal == preBal - collectAmt);
        } else {
            // when reverted, ensure that finalBal equals preBal (no change) — this holds on reference because revert prevents state change
            prop = (finalBal == preBal);
        }
        assertTrue(prop);
