pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit/collect and a flag to choose failing callee
    function testFuzz_property(uint128 depositAmount, uint128 collectAmount, bool useReverter) public {
        // keep values within reasonable gas / account bounds
        uint256 dep = uint256(bound(depositAmount, 1, 1 ether));
        uint256 col = uint256(bound(collectAmount, 1, 1 ether));

        // deploy either a normal receiver (that accepts) or a reverter that reverts on receive
        address receiver;
        if (useReverter) {
            Reverter r = new Reverter();
            receiver = address(r);
        } else {
            Receiver r = new Receiver();
            receiver = address(r);
        }

        // fund the actor who will call Put and then Collect
        address actor = address(0xABCD);
        vm.deal(actor, 2 ether);

        // set minimal config so the account meets MinSum condition
        vm.prank(actor);
        c.SetMinSum(0);
        vm.prank(actor);
        c.SetLogFile(address(c)); // log file can be any address with AddMessage; c has that
        vm.prank(actor);
        c.Initialized();

        // actor deposits 'dep' into their account via Put
        vm.prank(actor);
        c.Put{value: dep}(0);

        // ensure precondition satisfied: recorded balance >= collect amount and >= MinSum
        // if not, skip (fuzzer will try other values)
        uint256 beforeBal = c.Acc(actor).balance;
        vm.assume(beforeBal >= col);

        // attempt Collect that will trigger an external call to actor (via receiver address)
        // To route the low-level call to our receiver, we impersonate the actor address and set msg.sender to receiver by making the c call target the receiver as the recipient of funds:
        // However Collect sends to msg.sender; to make the low-level call go to our chosen failing/accepting contract,
        // we must have msg.sender be that contract. So we instead have the receiver contract call Collect on behalf of an account it controls.

        // We need an account inside the receiver that has balance in Acc mapping. So perform deposit from receiver.
        // First, fund receiver so it can deposit
        vm.deal(receiver, 2 ether);
        // receiver deposits
        if (useReverter) {
            // Reverter cannot call Put (its fallback reverts), but we still want an account that will receive Collect to be the reverter itself.
            // For Reverter we cannot deposit from it; instead, we will deposit from actor into Acc[reverterAddress] by making actor call Put but specifying msg.sender cannot be arbitrary.
            // Alternative approach: have an intermediate helper (Setter) that deposits into Acc for the reverter by calling Put via delegate? Not allowed.
            // Simpler: Use Receiver (accepting) when useReverter==false; when useReverter==true, we will have actor be the one whose address is the reverter
            // So switch roles: when useReverter==true, set actor = receiver (the Reverter) and fund it earlier.
            actor = receiver;
            // ensure funded
            vm.deal(actor, 2 ether);
            // deposit from reverter actor will fail because Reverter fallback reverts on receive, but Put is payable — depositing requires calling Put; Reverter has no code to call Put.
            // To deposit into Acc[reverter], have original actor (address 0xABCD) call Put but change msg.sender via prank to be actor (reverter)
            vm.prank(actor);
            // This will revert because Reverter has no code to call Put externally. Instead, we can have actor (EOA) call Put and then later Collect will send to that actor address which we choose to be the Reverter.
            // So revert to plan: do deposit from EOA (depositor) into Acc[depositor], and then have depositor's address be the reverter address. To accomplish the failing external call, the recipient of the send must be a contract that reverts on receive but also must have an Acc entry with balance.
            // To create such state, we will perform Put from an EOA, then change code at that address is impossible. So instead create a Receiver that accepts deposit and then replace it with Reverter — not possible.
            // Simpler and robust approach: The low-level call in Collect sends to msg.sender, so msg.sender must be a contract that will revert/accept on receive; that contract must also have an Acc entry with balance set by calling Put from that contract. Therefore we need helper contracts that can call Put to deposit and then later perform Collect as msg.sender.
            // So the correct approach is: both helpers (Receiver and Reverter) expose a method to call Put and to call Collect. We'll redesign helpers below. To keep file shape, revert to using helper contracts defined after this test and redeploy them here.
        }

        // Use improved helpers instead: redeploy helpers that can deposit and call Collect
        HelperReceiver hr = new HelperReceiver();
        HelperReverter hrev = new HelperReverter();
        address helper = useReverter ? address(hrev) : address(hr);

        // fund helper so it can send Put with value
        vm.deal(helper, 2 ether);

        // helper deposits 'dep' into its Acc entry by calling Put
        vm.prank(helper);
        C(payable(address(c))).Put{value: dep}(0);

        // sanity: recorded balance for helper
        uint256 helperBefore = c.Acc(helper).balance;
        vm.assume(helperBefore >= col);

        // now have helper call Collect to withdraw 'col' — Collect will send to msg.sender (helper) and helper's receive either accepts or reverts
        bool ok;
        try HelperCaller(helper).callCollect{value:0}(address(c), col) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect returns (either success or revert), the invariant for the correct contract: if Collect succeeded (ok==true), then recorded balance decreased by col; if Collect reverted, recorded balance unchanged.
        // We assert the property the reference must always satisfy: when call succeeds, the stored balance = before - col
        if (ok) {
            uint256 after = c.Acc(helper).balance;
            assertTrue(after == helperBefore - col);
        } else {
            // if it reverted, recorded balance should remain unchanged (Collect reverts in the reference as implemented), so after equals before
            uint256 after = c.Acc(helper).balance;
            assertTrue(after == helperBefore);
        }
    }
}

// Helper that accepts funds and can call Collect on C
contract HelperReceiver is HelperCaller {
    receive() external payable {}
}

// Helper that reverts on receive
contract HelperReverter is HelperCaller {
    receive() external payable { revert("no"); }
}

// Common interface: can call Collect on target contract
abstract contract HelperCaller {
    function callCollect(address target, uint256 amt) public payable {
        C(payable(target)).Collect(amt);
    }
}

